def minimalBases(classes):

    # Create a dictionary to store the base classes and their immediate subclasses
    base_dict = {}
    for cls in classes:
        for base in cls.__bases__:
            if base not in base_dict:
                base_dict[base] = {cls}
            else:
                base_dict[base].add(cls)

    # Define a function to check if a base class is minimal
    def is_minimal(base, subclasses):
        if len(base.__bases__) == 0:
            return True
        return len(subclasses) == 1 and subclasses.pop() == base

    # Iterate through the base classes and check if they are minimal
    minimal_bases = []
    for base, subclasses in base_dict.items():
        if is_minimal(base, subclasses):
            minimal_bases.append(base)

    # Return the list of minimal base classes
    return minimal_bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, list):
        raise TypeError("classes must be a list")

    seen = set()
    bases = []
    for cls in classes:
        if not isinstance(cls, type) or isinstance(cls, Constant):
            continue
        if cls not in seen:
            bases.append(cls)
            seen.add(cls)
            for base in cls.__bases__:
                if not base in seen:
                    seen.add(base)
                    bases.append(base)
    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = list(classes)
    while True:
        for i in range(len(bases)):
            base = bases[i]
            for j in range(len(bases)):
                if j >= i + 1 and issubclass(base, bases[j]) and base.mro()[-1] == bases[j]:
                    del bases[i]
                    break
            else:
                i += 1
        else:
            break
    return tuple(bases)

