def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("len(bins) must equal len(edges) - 1")

    integral = 0
    for i in range(len(bins)):
        integral += (edges[i] + edges[i + 1])/2 * (bins[i] + bins[i + 1])

    return integral

