def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        # Infinite recursion
        return {k: v for k, v in d1.items() if k not in d2}
    elif level == 0:
        # Only the first level is considered
        d1_keys = set(d1.keys())
        d2_keys = set(d2.keys())
        for k in d1_keys.intersection(d2_keys):
            if d1[k] != d2[k]:
                d1[k] = d1[k]
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        # Recursive
        diff = {}
        for k, v in d1.items():
            if k not in d2:
                diff[k] = v
            elif level > 1:
                v1 = difference(v, d2[k], level-1)
                if v1:
                    diff[k] = v1
        return diff

def difference(d1, d2, level=-1):
    if level == -1:
        # Infinite recursion
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        # Finite recursion
        d = dict(d1)
        for k, v in d.items():
            if k in d2:
                if isinstance(v, dict):
                    d[k] = difference(v, d2[k], level-1)
                elif v != d2[k]:
                    d[k] = v
            elif k not in d2:
                d.pop(k)
        return d

def difference(d1, d2, level=-1):
    if level == 0:
        # reached the maximum recursion depth, return d1
        return d1.copy()
    # initialize the difference dictionary
    diff = {}
    # iterate over all keys in d1
    for k in d1.keys():
        # if the key is not in d2, add it to the difference dictionary
        if k not in d2:
            diff[k] = d1[k]
        # if the key is in d2, but has a different value, add it to the difference dictionary
        elif d1[k] != d2[k] and level != 1:
            diff[k] = d1[k]
        # if the key is in d2 and has the same value, but the value is a dictionary, recursively call difference on the values
        elif level != 1:
            diff[k] = difference(d1[k], d2[k], level - 1)
    # return the difference dictionary
    return diff

def difference(d1, d2, level=-1):
    if isinstance(d1, dict) and isinstance(d2, dict):
        if level == -1:
            return difference(d1, d2, level + 1)
        result = {}
        for key in d1.keys():
            if key not in d2:
                result[key] = d1[key]
            else:
                val1 = d1[key]
                val2 = d2[key]
                if not isinstance(val1, dict):
                    if val1 != val2:
                        result[key] = val1
                else:
                    result[key] = difference(val1, val2, level + 1)
        return result
    elif isinstance(d1, dict) and not isinstance(d2, dict):
        return d1
    elif isinstance(d2, dict) and not isinstance(d1, dict):
        return d2
    else:
        raise ValueError("d1 and d2 should be a dictionary")

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _sub_difference(d1_, d2_, level_=level):
        if level_ == 0:
            return {}
        result = {}
        for key in d1_:
            if key in d2_:
                if d1_[key] != d2_[key]:
                    result[key] = d1_[key]
            else:
                result[key] = d1_[key]
        return result

    result = _sub_difference(d1, d2, level)
    for key in d2:
        if key not in d1:
            result[key] = d2_[key]
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """

    errors = []
    for key, value in labels.items():
        try:
            if not re.match(r'[a-zA-Z0-9._-]+$', key):
                raise ValidationError("Label key '{0}' does not match the regex [a-zA-Z0-9._-]+".format(key))
        except ValidationError:
            errors.append({"key": key})

        try:
            if not isinstance(value, (str, bytes)):
                raise ValidationError("Label value '{0}' is not a string or bytes-like object".format(value))
        except ValidationError:
            errors.append({"value": value})
    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        if not isinstance(key, (str, bytes)):
            message = {'key': key, 'value': 'expected string or bytes-like object'}
            messages.append(message)
        if not isinstance(value, (str, bytes)):
            message = {'key': value, 'value': 'expected string or bytes-like object'}
            messages.append(message)
        if not re.fullmatch(IDENTIFIER, key):
            message = {'key': key, 'value': "Label key '%s' does not match the regex %s" % (key, IDENTIFIER)}
            messages.append(message)
    if messages:
        raise ValidationError(messages)

