    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest.items():
        if resource.kind != "Deployment":
            continue
        if resource.kind != "Namespace":
            continue
        if resource.kind != "ReplicaSet":
            continue
        if resource.kind != "Pod":
            continue
        if resource.kind != "Statefulset":
            continue
        if resource.kind != "ConfigMap":
            continue
        if resource.kind != "Service":
            continue

        if resource.metadata.time_of_update > app.active_since:
            continue

        if resource.metadata.time_of_delete:
            continue

        if resource.metadata.generation > app.revision:
            continue

        if resource.metadata.namespace != app.namespace:
            continue

        if app.custom_observer_schema and resource.kind in app.custom_observer_schema:
            continue

        app.default_observer_schema[resource.kind] = resource.metadata

    return app.default_observer_schema

