    # If everything is okay, return the fixity block
    return fixity

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    if not self.file.exists():
        raise ValueError("File \"%s\" doesn't exists")

    for fixity_result in fixity:
        if fixity_result['filename'] not in manifest_files:
            raise ValueError("Fixity report for unknown file: %s" % fixity_result['filename'])

        if 'sha1' not in fixity_result and 'md5' not in fixity_result:
            raise ValueError("Fixity report for file \"%s\" does not contain sha1 or md5 hash" % fixity_result['filename'])

    print("Fixity block in inventory is consistent with the manifest files.")

