        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    result = {}
    for xml in xmls:
        filename = xml.get('metadata', {}).get('name', '').lower()
        if filename not in result:
            result[filename] = {}
        result[filename][xml.get('header', {}).get('package', '').lower()] = xml
