def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    output = ""
    for key, value in self.items():
        if isinstance(value, dict):
            output += "{} {{\n".format("  " * indent)
            output += pretty(value, indent + 1, debug)
            output += "{} }}".format("  " * indent)
        else:
            output += "{}{}: {}\n".format("  " * indent, key, value)
    return output.strip()

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    absorbed = []
    for arg in args:
        if isinstance(arg, LogicalAnd):
            if arg.left == arg.right:
                absorbed.append(arg.left)
            elif arg.left == Not(arg.right):
                absorbed.append(True)
            else:
                absorbed.append(arg)
        elif isinstance(arg, LogicalOr):
            if arg.left == arg.right:
                absorbed.append(arg.left)
            elif arg.left == Not(arg.right):
                absorbed.append(False)
            else:
                absorbed.append(arg)
        else:
            absorbed.append(arg)
    return absorbed

