def render(pieces, style):
    # Check if the given pieces and style are valid
    if not pieces or not style:
        raise ValueError("Invalid input for 'pieces' or 'style', cannot render")

    # Check if the given style is supported
    if style not in SUPPORTED_STYLES:
        raise ValueError("The given style is not supported, cannot render")

    # Check if all the pieces have the required format
    if not all(isinstance(piece, tuple) and len(piece) == 2 for piece in pieces):
        raise ValueError("Invalid format of 'pieces', cannot render")

    # Sort the pieces by the first element of the tuple
    sorted_pieces = sorted(pieces, key=lambda x: x[0])

    # Check if any of the pieces have the same first element
    if len(set(piece[0] for piece in sorted_pieces)) != len(sorted_pieces):
        raise ValueError("Duplicate first element found in 'pieces', cannot render")

    # Render the pieces based on the requested style
    if style == "markup":
        content = ""
        for piece in sorted_pieces:
            if piece[1] == None:
                content += piece[0]
            else:
                content += "%s%s" % (piece[0], piece[1])
        return content
    elif style == "html":
        content = """"""
        for piece in sorted_pieces:
            if piece[1] == None:
                content += piece[0]
            else:
                content += """<span style="font-weight: bold;">%s</span>%s""" % (piece[0], piece[1])
        return content
    elif style == "latex":
        content = """"""
        for piece in sorted_pieces:
            if piece[1] == None:
                content += piece[0]
            else:
                content += """\textit{%s}\textbf{%s}""" % (piece[0], piece[1])
        return content
    else:
        raise ValueError("The given style is not supported, cannot render")

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    rendered_pieces = []
    for piece in pieces:
        if isinstance(piece, str):
            rendered_pieces.append(piece)
        elif isinstance(piece, dict):
            rendered_pieces.append(str(piece[style]))
        else:
            raise ValueError("Unsupported type for version piece: {}".format(type(piece)))
    return "".join(rendered_pieces)

