def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    output = None
    try:
        if isinstance(commands, list):
            command = commands[0]
            for arg in args:
                if arg is not None:
                    command += "{}".format(arg)
            process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, echo=False, cwd=cwd, env=env)
            output, _ = process.communicate()
            if hide_stderr:
                output = ""
        else:
            raise TypeError("commands should be iterable of strings")
    except TypeError:
        output = None
    except subprocess.CalledProcessError:
        output = None
    except OSError as e:
        error_message = "{}".format(e)
        if verbose:
            sys.stderr.write(error_message)
        raise ProgramError(error_message)
    return output

