def validate_hierarchy(
        self, validate_objects=True, check_digests=True, show_warnings=False
    ):

        """Validate storage root hierarchy.

        Args:
            validate_objects: If True and full validation is enabled, will perform object validation. Default True.
            check_digests: If True will calculate the digest of each file to verify integrity. Default True.
            show_warnings: If True will log any issues that occur during validation. Default False.

        @NOTE: This method is not part of Open Storage Spec.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid

        """
        # Implemented from test.states.SelfTestCase

        self.seek_start()

        root_node = self.get_root_node()
        self.assertTrue(root_node, "Failed to find root node")

        num_objects = 0
        good_objects = 0

        for depth_type in self.DIRECTORY_SCAN_ORDER:
            nodes = self.get_nodes(root_node, depth_type)
            for node in nodes:
                num_objects += 1

                if not validate_objects or node.is_direct() or node.inode:
                    good_objects += 1
                    continue

                if check_digests:
                    digest = self.calculate_digest(node.path)

                    if not digest.is_valid():
                        if show_warnings:
                            self.log.warning(
                                "Object is potentially corrupt: %s" % node.path
                            )
                    elif digest.is_tampered():
                        if show_warnings:
                            self.log.warning(
                                "Object is known to be stale: %s" % node.path
                            )
                    else:
                        good_objects += 1
                    continue

        self.seek_start()

        return num_objects, good_objects

