def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        raise ValueError("Invalid version")

    major, minor = version.split(".")
    if minor == '*':
        minor = 0
        rev = 1
    else:
        rev = int(minor) + 1

    if rev > 0 and rev < 10:
        if minor.startswith("0"):
            minor = f"0{rev}"
        else:
            minor = str(rev)
    else:
        rev = 0
        major = int(major) + 1

    return f"{major}.{minor}.{rev}"

def validate_version_inventories(self, version_dirs) -> List[Tuple[str, Set[str]]]:
    """
    Each version SHOULD have an inventory up to that point. Also keep a record of any content digests different from those in the root inventory so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in version sequence (1, 2, 3...).

    Raises:
        InvalidArgumentError: If the argument `version_dirs` is not a list of strings.
        InconsistentStateError: If the inventory found in any of the version directories does not match the expected format of the root inventory.
        InvalidInventoryError: If the digest of any of the files in any of the version directories is different from that in the root inventory.

    Returns:
        A list of tuples, where each tuple contains the name of a version directory as a string, and a set of all the digests (SHA1 hashes) of the files in that version directory that are different from those in the root inventory.
    """
    if not isinstance(version_dirs, list) or not all(isinstance(version, str) for version in version_dirs):
        raise InvalidArgumentError("The argument `version_dirs` must be a list of strings.")

    inventories = []
    for version in version_dirs:
        try:
            inventory = version.get_inventory()
        except InventoryError:
            raise InconsistentStateError(f"The inventory found in version {version} does not match the expected format.")
        else:
            inventories.append(inventory)

    digests = set()
    for inventory in inventories:
        for file in inventory:
            file_digest = file.get_digest()
            if file_digest not in digests:
                digests.add(file_digest)
        for digest in digests:
            if digest not in inventory:
                raise InvalidInventoryError(f"The digest {digest} is missing in version {version}.")

def find_path_type(path):
    if "0=*" in path:
        return "object"
    elif os.path.isdir(path):
        return "root"
    elif os.path.isfile(path):
        return "file"
    else:
        return "other"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        raise ValueError("Path is required.")

    if not os.path.exists(path):
        raise ValueError(f"Path {path} does not exist.")

    if os.path.isfile(path):
        file_content = Path(path).read_text(encoding="UTF-8")
        if "ocfl_object" in file_content:
            return "object"
        elif "0=*" in file_content:
            return "inventory"
        else:
            return "file"
    elif os.path.isdir(path):
        if os.path.exists(os.path.join(path, "0=*")):
            return "root"
        else:
            return "directory"
    else:
        raise ValueError(f"Path {path} is not recognized as a file or directory.")

def find_path_type(path):
