        """
        Given command-line arguments with which this script was invoked, parse the arguments and return
        them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
        """

        # Create an empty dict to store parsed arguments
        parsed_arguments = {}

        # Loop through each argument and extract its name and value
        for argument in unparsed_arguments:
            # Check if argument is a subparser
            if argument.startswith("--"):
                # If it is a subparser, parse all following arguments as if they belong to that subparser
                subparser_name = argument[2:]
                subparser_args = []
                while True:
                    next_argument = unparsed_arguments.pop(0)
                    if next_argument.startswith("--"):
                        break
                    subparser_args.append(next_argument)
                parsed_arguments[subparser_name] = parse_arguments(*subparser_args)
            else:
                # If it is not a subparser, use the given argument as a key in the dict and the next argument as its value
                try:
                    next_argument = unparsed_arguments.pop(0)
                except IndexError:
                    raise ValueError("Invalid number of arguments provided")
                parsed_arguments[argument] = next_argument

        # Use argparse to convert the parsed arguments into an argparse.Namespace instance
        parser = argparse.ArgumentParser(description="Process command-line arguments")
        for key, value in parsed_arguments.items():
            if isinstance(value, dict):
                namespace = parse_arguments(value)
                parser.add_argument(key, action=argparse.NamespaceAction, namespace=namespace)
            else:
                parser.add_argument(key, type=str, default=value)
        parsed_arguments = parser.parse_args()

        # Return the parsed arguments as a dict mapping from subparser name to argparse.Namespace instance
        return parsed_arguments

