def merge_mappings(existing_mapping, new_mapping):
    result = {
        ScalarNode(tag='tag:yaml.org,2002:str', value=key): value
        for key, value in existing_mapping.value
    }
    result.update({
        ScalarNode(tag='tag:yaml.org,2002:str', value=key): value
        for key, value in new_mapping.value
    })
    return MappingNode(tag='tag:yaml.org,2002:map', value=result.items())

def deep_merge_nodes(nodes):
