def size_to_bytes(size: str) -> int:
    if not size:
        return 0

    size = size.upper()
    if size[-1] in ("B", "BYTES"):
        return int(size[:-2])

    mag = {"K": 1000, "M": 1000000, "G": 1000000000, "T": 1000000000000, "P": 1000000000000000, "E": 1000000000000000000, "Z": 1000000000000000000000, "Y": 1000000000000000000000000}
    if size[-1] in mag:
        return int(size[:-1]) * mag[size[-1]]

    raise ValueError("Invalid input string")

