def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Extract the URL arguments from the URL
    args_positions = [(m.start(), m.end()) for m in re.finditer(r"{[a-zA-Z0-9_]+}", url)]

    # Replace each argument with the corresponding value from url_args
    for arg_position, arg_name in args_positions:
        if arg_name in url_args:
            url = url[:arg_position] + url_args[arg_name] + url[arg_position+1:]
