def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("The input number must be an integer.")
    if not isinstance(alphabet, list):
        raise ValueError("The alphabet must be a list of strings.")
    for char in alphabet:
        if not isinstance(char, str):
            raise ValueError("The alphabet must contain only strings.")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("The padding parameter must be an integer or None.")

    if padding is not None and padding < 0:
        raise ValueError("The padding parameter must be a non-negative integer.")

    output = ""
    while number > 0:
        output = alphabet[number % len(alphabet)] + output
        number //= len(alphabet)

    if padding is not None and len(output) < padding:
        output = (padding - len(output)) * "0" + output

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if len(alphabet) < 2:
        raise ValueError("alphabet must have at least 2 elements")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    base = len(alphabet)
    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    result.reverse()
    return "".join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Negative number cannot be converted to a string.")

    base = len(alphabet)

    if padding is not None:
        if padding < 0:
            raise ValueError("Padding value cannot be negative.")
        padding_diff = padding - len(str(number))
        if padding_diff > 0:
            number = "%0*" + str(padding_diff) + "d" % number

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    return "".join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("padding must be a non-negative integer")

    base = len(alphabet)
    if number < 0:
        raise ValueError("number must be a non-negative integer")

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return "".join(result[::-1])

