    if not os.path.exists(tmp_path):
        raise OSError(F"The temporary path '{tmp_path}' does not exist.")

    tmp_dir = os.path.join(tmp_path, filename)
    if os.path.exists(tmp_dir):
        raise FileExistsError(f"The temporary directory '{tmp_dir}' already exists.")

    try:
        with TemporaryDirectory(dir=tmp_path, prefix=filename) as tmp_dir:
            subprocess.run(["tar", "-xf", archive_path, "-C", tmp_dir]).check_returncode()
            return tmp_dir
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract the archive '{filename}' to '{tmp_dir}'.") from e

