    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    config_filepath = os.path.join(os.path.expanduser("~"), config_filename)
    if not overwrite and os.path.isfile(config_filepath):
        return
    else:
        try:
            config_path_dirname = os.path.dirname(config_filepath)
            os.makedirs(config_path_dirname)
        except OSError:
            if not os.path.isdir(config_path_dirname):
                raise
        with open(config_filepath, "wb") as f:
