def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    if not (callable(func) and isinstance(func, types.FunctionType)):
        raise TypeError('func must be a function')

    env = extra_env if extra_env else dict()
    process = subprocess.run(func.__module__ + '.' + func.__name__, *args, capture_output=True, env=env, timeout=timeout, text=True)
    if process.returncode != 0:
