    if extra_env is None:
        extra_env = {}
    # Construct the full command line
    cmd = [func, *args]
    # Get the status of the process
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, env=extra_env)
    return p.returncode

