def replace_between_tags(text, repl_, start_tag, end_tag=None):
    new_lines = []
    editing = False
    lines = text.split('\n')
    for line in lines:
        if not editing:
            new_lines.append(line)
        if line.strip().startswith(start_tag):
            new_lines.append(repl_)
            editing = True
        if end_tag is not None and line.strip().startswith(end_tag):
            editing = False
            new_lines.append(line)
    new_text = '\n'.join(new_lines)
    return new_text

def find_tags(text, replacer=None):
    tag_pattern = r"^(?!\w).*#([^#\\n, ]+)(\S)*"
    tags = set()
    for match in re.finditer(tag_pattern, text, re.MULTILINE):
        tags.add(match.group(1))
        if replacer:
            text = text.replace(match.group(0), replacer(match.group(1)))
    return tags, text

