def parse_xrd(document: str) -> Dict:
    """
    Parse XRD document.
    """
    root = ElementTree.fromstring(document)
    data = {}
    for sub_element in root.findall(".//*[@rel='operation type: http://joindiaspora.com/web_asgtvntmrim']"):
        data["url"] = sub_element.attrib["href"]
    for sub_element in root.findall(".//*[@rel='lrdd']"):
        data["lrdd_url"] = sub_element.attrib["href"]
    for sub_element in root.findall(".//*[@rel='httpd']"):
        data["hcard_url"] = sub_element.attrib["href"]
    for sub_element in root.findall(".//*[@rel='profile']/a"):
        data["profile"] = sub_element.text
    return data

