    settings_dirs = settings_dirs or []
    file_names = []
    for directory in settings_dirs:
        try:
            file_names += sorted(
                fname
                for fname in os.listdir(directory)
                if fname.endswith(".spec") and fname.startswith(spec_option)
            )
