def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        data_dict = yaml.load(spec_content, Loader=yaml.SafeLoader)
        required_fields = ['type', 'schema', 'json_schema', 'dummy_rows', 'seed']
        for field in required_fields:
            if field not in data_dict:
                raise ValidationError(f"'{field}' is a required field but is missing in the spec file.")
        return data_dict
    except ValidationError as e:
        raise IRValidatorException(str(e))

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise TypeError("yaml_file argument must be supplied")
    if not isinstance(yaml_file, Path):
        raise TypeError("yaml_file argument must be a Path object")

    try:
        with yaml_file.open() as f:
            data = yaml.load(f)
    except Exception as e:
        raise IRValidatorException("Error loading yaml_file", e)

    try:
        cls.validate(data)
    except ValidationError as ve:
        raise IRValidatorException(ve.message)

    return data

