    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    if ir_workspace is None or ir_plugin is None or playbook_path is None:
        raise ValueError("ir_workspace, ir_plugin, and playbook_path are required")
    if verbose is None:
        verbose = "v"
    if extra_vars is None:
        extra_vars = ()
    if ansible_args is None:
        ansible_args = ()
    workspace = ir_workspace.workspace
    workspace_id = ir_workspace.id
    playbook_file = ir_plugin.playbooks.get_path(playbook_path)
    logger.info(f"Running Ansible playbook {playbook_file} in workspace {workspace_id}")
    args = [workspace_id, playbook_file, "--extra-vars", str(extra_vars), "--ansible-args", str(ansible_args)]
    if verbose:
        args.insert(1, verbose)
    try:
        _ = subprocess.check_output(["ansible-playbook"] + args, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        if e.returncode == 1:
            raise Exception("Ansible playbook failed")
        else:
            raise Exception("CalledProcessError with return code {e.returncode}")
    logger.info(f"Ansible playbook completed successfully")

