def get_plugin_spec_flatten_dict(plugin_dir):
    # Collect all files in the plugin directory
    file_list = []
    for root, dirs, files in os.walk(plugin_dir):
        file_list.extend([os.path.join(root, file) for file in files])

    # Collect all plugin property files
    property_files = []
    for file in file_list:
        if file.endswith(".properties"):
            property_files.append(file)

    # Create an empty plugin dictionary
    plugin_dict = {}

    # For each property file, read the properties and update the plugin dictionary
    for property_file in property_files:
        with open(property_file, "r") as f:
            properties = f.read().splitlines()
            for property in properties:
                key, value = property.split("=")
                plugin_dict[key] = value

    return plugin_dict

