    """Remove root from path, throw exception on failure."""
    # Ensure that root is a directory containing path
    if not os.path.isdir(root):
        raise ValueError("Root '{0}' is not a directory".format(root))
    if not path.startswith(root):
        raise ValueError("Path '{0}' is not a subpath of root '{1}'".format(path, root))

